parameters.jsCode:
const input = $input.first()?.json ?? {};

const action = input.action ?? null;
const params = input.params ?? {};
const session_id = input.session_id ?? null;
const message = input.message ?? "";

if (!action) {
  throw new Error("Missing action");
}

if (!session_id) {
  throw new Error("Missing session_id");
}

if (!params || typeof params !== "object") {
  throw new Error("Missing params object");
}

if (!params.usecase_name) {
  throw new Error("Missing params.usecase_name");
}

return [{
  json: {
    action,
    params,
    session_id,
    message
  }
}];

const original = $('Validate Builder Input').first().json;

const dictionaryRows = $input.all()
  .map(item => item.json)
  .filter(row => row && Object.keys(row).length > 0 && row.usecase_parameter_name);

const dictionary_parameters = dictionaryRows.map(row => ({
  dict_entry: row.dict_entry,
  usecase_name: row.usecase_name,
  name: row.usecase_parameter_name,
  format: row.parameter_format,
  required: Boolean(row.is_required),
  description: row.description ?? "",
  param_value: row.param_value ?? null,
  api_pool_id: row.api_pool_id ?? null
}));

const api_pool_id =
  dictionary_parameters.find(p => p.api_pool_id != null)?.api_pool_id ?? null;

return [{
  json: {
    action: original.action,
    params: original.params,
    dictionary_parameters,
    api_pool_id,
    session_id: original.session_id,
    message: original.message
  }
}];

const ctx = $('Prepare Builder Context').first().json;
const apiPoolRow = $input.first().json ?? {};

const params = ctx.params ?? {};
const dictionary = ctx.dictionary_parameters ?? [];

function findParam(...names) {
  return dictionary.find(p =>
    names.includes(String(p.name).toLowerCase())
  );
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value !== null && value !== undefined && value !== "") {
      return value;
    }
  }
  return null;
}

function safeJsonParse(value) {
  if (value == null || value === "") return null;
  if (typeof value === "object") return value;

  try {
    return JSON.parse(value);
  } catch (error) {
    return value;
  }
}

const endpointParam = findParam("url", "endpoint", "endpoint_url", "base_url");
const valuePathParam = findParam("response_value_path", "value_path", "json_path");
const measurementParam = findParam("measurement_name", "value_name", "measure");
const currentParam = findParam("current");

const parsedParamSchema = safeJsonParse(apiPoolRow.param_schema);
const parsedSampleResponse = safeJsonParse(apiPoolRow.sample_response);

const inferredResponseValuePath = (() => {
  const explicitPath = firstNonEmpty(
    params.response_value_path,
    valuePathParam?.param_value
  );

  if (explicitPath) return explicitPath;

  const currentValue = firstNonEmpty(
    currentParam?.param_value,
    parsedParamSchema?.current
  );

  if (currentValue) {
    return `current.${currentValue}`;
  }

  return "";
})();

const apiMetadata = {
  api_name:
    firstNonEmpty(
      params.api_name,
      params.name,
      apiPoolRow.name,
      params.usecase_name
    ) ?? "",

  usecase_name:
    params.usecase_name ?? "",

  source_api_name:
    apiPoolRow.name ?? null,

  api_pool_id:
    apiPoolRow.id ?? null,

  endpoint_url:
    firstNonEmpty(
      params.endpoint_url,
      endpointParam?.param_value,
      apiPoolRow.endpoint_url
    ),

  method:
    firstNonEmpty(apiPoolRow.method, "GET"),

  auth_type:
    firstNonEmpty(apiPoolRow.auth_type, "none"),

  auth_header:
    apiPoolRow.auth_header ?? null,

  response_value_path:
    inferredResponseValuePath,

  measurement_name:
    firstNonEmpty(
      params.measurement_name,
      measurementParam?.param_value,
      currentParam?.param_value,
      parsedParamSchema?.current,
      params.usecase_name
    ) ?? "",

  description:
    apiPoolRow.description ?? "",

  context:
    params.context ?? "",

  param_schema:
    parsedParamSchema,

  sample_response:
    parsedSampleResponse,

  required_query_parameters: dictionary
    .filter(p => {
      const name = String(p.name).toLowerCase();
      return ![
        "url",
        "endpoint",
        "endpoint_url",
        "base_url",
        "response_value_path",
        "value_path",
        "json_path",
        "measurement_name",
        "value_name",
        "measure"
      ].includes(name);
    })
    .map(p => ({
      name: p.name,
      format: p.format,
      required: p.required,
      description: p.description,
      param_value: p.param_value,
      api_pool_id: p.api_pool_id
    }))
};

return [{
  json: {
    ...ctx,
    api_pool_sample: {
      ...apiPoolRow,
      param_schema: parsedParamSchema,
      sample_response: parsedSampleResponse
    },
    api_metadata: apiMetadata
  }
}];

const input = $input.first().json;

const raw =
  input.text ??
  input.output ??
  input.response ??
  input.result ??
  "";

const cleaned = String(raw)
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    "Use Case Builder AI did not return valid JSON. Raw output was: " + cleaned
  );
}

if (!parsed.usecase_name) {
  throw new Error("AI output is missing usecase_name");
}

if (!parsed.summary) {
  parsed.summary = "";
}

if (!Array.isArray(parsed.steps)) {
  throw new Error("AI output is missing steps array");
}

return [{
  json: {
    ...parsed,
    session_id: $("Build Builder Prompt").first().json.session_id
  }
}];

const foundNodeKeys = parsed.nodes.map(node => node.node_key);

const missingNodeKeys = requiredNodeKeys.filter(
  key => !foundNodeKeys.includes(key)
);

if (!Array.isArray(parsed.required_researcher_checks)) {
  parsed.required_researcher_checks = [];
}

if (!Array.isArray(parsed.warnings)) {
  parsed.warnings = [];
}

if (missingNodeKeys.length > 0) {
  parsed.warnings.push(
    `Missing generated sections: ${missingNodeKeys.join(", ")}`
  );
}

return [{
  json: {
    ...parsed,
    session_id: $("Build Builder Prompt").first().json.session_id
  }
}];

const data = $input.first().json;

function formatGeneratedContent(content) {
  if (typeof content === "string") {
    return content;
  }

  return JSON.stringify(content, null, 2);
}

let reply = `Use Case Builder output for **${data.usecase_name}**\n\n`;

if (data.summary) {
  reply += `${data.summary}\n\n`;
}

reply += `Follow these steps in the Vibration Orchestrator template:\n\n`;

for (const step of data.steps ?? []) {
  reply += `## ${step.step_number}. ${step.title}\n`;

  if (step.node_to_open) {
    reply += `**Open node:** ${step.node_to_open}\n`;
  }

  if (step.field_to_change) {
    reply += `**Change:** ${step.field_to_change}\n\n`;
  }

  if (step.generated_content !== undefined && step.generated_content !== "") {
    reply += "```text\n";
    reply += formatGeneratedContent(step.generated_content);
    reply += "\n```\n";
  }

  if (step.explanation) {
    reply += `${step.explanation}\n`;
  }

  reply += "\n";
}

reply += `That is all the researcher needs to change. The remaining template nodes can stay as they are.\n`;

return [{
  json: {
    reply,
    session_id: data.session_id
  }
}];
